/**
 * Committed adversarial `.bgcode` corpus (test-data/fixtures/bgcode/adversarial/, generated by
 * tools/fixtures/make-bgcode-adversarial.mjs). Each file must fail with its literal structured code.
 */
import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ContainerError } from '@chestnutlabs/gcode-containers';
import { openBgcode } from '../index.js';

const dir = join(dirname(fileURLToPath(import.meta.url)), '../../../../test-data/fixtures/bgcode/adversarial');
const load = (name: string): Uint8Array => new Uint8Array(readFileSync(join(dir, name)));

const CASES: Array<[file: string, code: string, message: string, maxOutputBytes?: number]> = [
  ['deflate-over-declared.bgcode', 'E_BGCODE_BOMB', 'deflate output exceeds the declared/limit size (100)'],
  ['checksum-type-2.bgcode', 'E_BGCODE_CHECKSUM', 'unknown checksum type 2'],
  ['truncated-crc.bgcode', 'E_BGCODE_TRUNCATED', 'truncated block checksum'],
  ['meatpack-bad-cmd.bgcode', 'E_BGCODE_MEATPACK', 'invalid MeatPack command 0 at byte 2'],
  ['aggregate-over-cap.bgcode', 'E_BGCODE_BOMB', 'decoded G-code exceeds the output limit (120)', 100],
  ['unknown-encoding.bgcode', 'E_BGCODE_UNSUPPORTED_ENCODING', 'unknown gcode encoding id 3']
];

describe('adversarial .bgcode fixtures fail with their documented error', () => {
  for (const [file, code, message, maxOutputBytes] of CASES) {
    it(`${file} → ${code}`, async () => {
      const err = await openBgcode(load(file), maxOutputBytes === undefined ? {} : { maxOutputBytes }).then(
        () => undefined,
        (e: unknown) => e
      );
      expect(err).toBeInstanceOf(ContainerError);
      expect((err as ContainerError).code).toBe(code);
      expect((err as ContainerError).message).toBe(message);
    });
  }

  it('aggregate-over-cap.bgcode decodes fully when the cap allows 120 bytes', async () => {
    expect((await openBgcode(load('aggregate-over-cap.bgcode'), { maxOutputBytes: 120 })).gcode.length).toBe(120);
  });
});
